record.field:
for record in records:
    if (
        record.x_studio_start_date
        and record.x_studio_membership_plan
        and record.x_studio_membership_plan.x_studio_duration_months
    ):
        months = int(record.x_studio_membership_plan.x_studio_duration_months)

        end_date = (
            record.x_studio_start_date
            + dateutil.relativedelta.relativedelta(months=months)
            - dateutil.relativedelta.relativedelta(days=1)
        )

        record.write({
            'x_studio_end_date': end_date
        })

for record in records:
    if record.x_studio_status == "In Progress":
        record.write({
            "x_studio_start_time": datetime.datetime.now(),
        })

for record in records:
    if record.x_studio_status == "Completed":
        if not record.x_studio_start_time:
            raise UserError("Cannot check out before checking in.")

        record.write({
            "x_studio_end_time": datetime.datetime.now(),
        })

for record in records:
    if record.x_studio_status == "Cancelled":
        record.write({
            "x_active": False,
        })

for record in records:
    if not record.x_studio_member or not record.x_studio_membership_plan:
        continue

    # Check if an invoice already exists
    existing_invoice = env['account.move'].search([
        ('move_type', '=', 'out_invoice'),
        ('x_studio_enrollment_id', '=', record.id),
        ('state', '!=', 'cancel'),
    ], limit=1)

    if existing_invoice:
        raise UserError(
            "An invoice has already been created for this enrollment.\n\n"
            "Invoice: %s" % existing_invoice.name
        )

    invoice_lines = []

    # Membership Plan
    invoice_lines.append((0, 0, {
        'name': record.x_studio_membership_plan.x_name,
        'quantity': 1,
        'price_unit': (
            record.x_studio_membership_plan.x_studio_value *
            record.x_studio_membership_plan.x_studio_duration_months
        ),
    }))

    # Fitness Class
    if record.x_studio_fitness_class:
        invoice_lines.append((0, 0, {
            'name': record.x_studio_fitness_class.x_name,
            'quantity': 1,
            'price_unit': (
                record.x_studio_fitness_class.x_studio_value *
                record.x_studio_membership_plan.x_studio_duration_months
            ),
        }))

    # Personal Training
    if record.x_studio_personal_training:
        invoice_lines.append((0, 0, {
            'name': record.x_studio_personal_training.x_name,
            'quantity': 1,
            'price_unit': (
                record.x_studio_personal_training.x_studio_value *
                record.x_studio_membership_plan.x_studio_duration_months
            ),
        }))

    # Create Invoice
    invoice = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': record.x_studio_member.id,
        'invoice_date': datetime.date.today(),
        'x_studio_enrollment_id': record.id,
        'invoice_line_ids': invoice_lines,
    })

    # Save Invoice reference in Enrollment
    record.write({
        'x_studio_invoice_1': invoice.id,
    })

for record in records:
    if record.x_studio_personal_training:
        record.write({
            'x_studio_trainer':
                record.x_studio_personal_training.x_studio_trainer.id
        })
    else:
        record.write({
            'x_studio_trainer': False
        })

for record in records:
    if record.x_studio_status == 'Active':
        record.write({
            'x_active': True
        })
    elif record.x_studio_status == 'Cancelled':
        record.write({
            'x_active': False
        })

for record in records:
    if record.x_studio_member:
        member = record.x_studio_member
        # 1. Add member to the current fitness class if set and enrollment is Active
        if record.x_studio_fitness_class and record.x_studio_status == 'Active':
            if member not in record.x_studio_fitness_class.x_studio_members:
                record.x_studio_fitness_class.write({
                    'x_studio_members': [(4, member.id)]
                })

        # 2. Clean up any fitness classes where this member is registered but has no Active enrollments
        all_classes = env['x_fitness_classes'].search([('x_studio_members', 'in', member.id)])
        for fitness_class in all_classes:
            active_enrollment_count = env['x_enrollment'].search_count([
                ('x_studio_member', '=', member.id),
                ('x_studio_fitness_class', '=', fitness_class.id),
                ('x_studio_status', '=', 'Active')
            ])
            if active_enrollment_count == 0:
                fitness_class.write({
                    'x_studio_members': [(3, member.id)]
                })

for record in records:
    if record.x_studio_status in ['Cancelled', 'Expired', 'Renewed']:
        continue
    if not record.x_studio_fitness_class:
        continue

    fitness_class = record.x_studio_fitness_class
    member = record.x_studio_member

    # Check if the member is already enrolled in the class
    is_member_enrolled = member and (member.id in fitness_class.x_studio_members.ids)

    current_count = len(fitness_class.x_studio_members)
    projected_count = current_count if is_member_enrolled else (current_count + 1)

    if projected_count > fitness_class.x_studio_maximum_capacity:
        raise UserError(
            "The fitness class '%s' has reached its maximum capacity of %s members."
            % (fitness_class.x_name, fitness_class.x_studio_maximum_capacity)
        )

for record in records:
    if record.x_studio_selection_1 == 'Active':
        record.write({
            'x_active': True
        })
    elif record.x_studio_selection_1 == 'Cancelled':
        record.write({
            'x_active': False
        })

for record in records:
    if record.x_studio_status == 'Active':
        record.write({
            'x_active': True
        })
    elif record.x_studio_status == 'Cancelled':
        record.write({
            'x_active': False
        })

for record in records:
    if record.payment_state == 'paid' and record.x_studio_enrollment_id:
        record.x_studio_enrollment_id.write({
            'x_studio_status': 'Active',
        })

for record in records:
    record.write({
        'x_studio_status': 'Cancelled',
        'x_active': False,
    })

for record in records:

    new_enrollment = env['x_enrollment'].create({
        'x_name': 'New',  # Replace with your enrollment number logic
        'x_studio_member': record.x_studio_member.id,
        'x_studio_membership_plan': record.x_studio_membership_plan.id,
        'x_studio_trainer': record.x_studio_trainer.id if record.x_studio_trainer else False,
        'x_studio_fitness_class': record.x_studio_fitness_class.id if record.x_studio_fitness_class else False,
        'x_studio_personal_training': record.x_studio_personal_training.id if record.x_studio_personal_training else False,
        'x_studio_start_date': datetime.date.today(),
    })

    # Archive current enrollment
    record.write({
        'x_active': False,
        'x_studio_status': 'Renewed',

    })

    action = {
        'type': 'ir.actions.act_window',
        'res_model': 'x_enrollment',
        'view_mode': 'form',
        'res_id': new_enrollment.id,
        'target': 'current',
    }

for record in records:
    if record.x_name == 'New' or not record.x_name:
        seq = env['ir.sequence'].next_by_code('x_enrollment') or 'New'
        while seq != 'New' and env['x_enrollment'].search_count([('x_name', '=', seq)]) > 0:
            seq = env['ir.sequence'].next_by_code('x_enrollment') or 'New'
        record.write({
            'x_name': seq
        })

for record in records:
    if record.x_name and record.x_name != 'New':
        if env['x_enrollment'].search_count([('x_name', '=', record.x_name), ('id', '!=', record.id)]) > 0:
            raise UserError("The Enrollment Number '%s' must be unique!" % record.x_name)

for record in records:
    # 1. Send email to Member using template
    if record.x_studio_member and record.x_studio_member.email:
        template = env.ref('fitness_center_saas.email_template_enrollment_activation_member', raise_if_not_found=False)
        if template:
            template.send_mail(record.id, force_send=True)

    # 2. Send email to Trainer using template
    if record.x_studio_trainer and record.x_studio_trainer.work_email:
        template = env.ref('fitness_center_saas.email_template_enrollment_activation_trainer', raise_if_not_found=False)
        if template:
            template.send_mail(record.id, force_send=True)

for record in records:
    if record.x_studio_personal_training:
        record.write({
            'x_studio_trainer_1': True,
        })

for record in records:
    if record.x_studio_duration_months is False or record.x_studio_duration_months <= 0:
        raise UserError("Duration must be greater than 0.")

for record in records:
    if record.x_studio_invoice_1:
        raise UserError("This enrollment cannot be modified because an invoice has already been created.")
